def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def check_divisibility(n):
    D_n = D(n)
    numerator = 20**(n+1)

    # Check if D_n divides numerator
    if D_n == 0:
        return "D(n) is zero, undefined case"

    is_divisible = (numerator % D_n == 0)
    return is_divisible

N_values = [5, 6, 7, 8]
results_5_8 = {}
for n in N_values:
    result = check_divisibility(n)
    results_5_8[n] = result

print("Results for n=5, 6, 7, 8:")
for n, result in results_5_8.items():
    print(f"n={n}: D(n)={D(n)}, Divisibility holds: {result}")

# Now check n=0, 1, 2, 3, 4 for patterns
print("\nResults for n=0, 1, 2, 3, 4:")
results_0_4 = {}
for n in range(5):
    result = check_divisibility(n)
    results_0_4[n] = result

